cd /home/galbot/.pi/agent/sessions; for f in $(ls -t */*.jsonl | head -12); do echo "== $f"; python3 -c "
import json,sys
p=sys.argv[1]
for line in open(p):
    try: d=json.loads(line)
    except: continue
    m=d.get('message',{})
    if m.get('role')=='user':
        c=m.get('content')
        t=c if isinstance(c,str) else ' '.join(x.get('text','') for x in c if isinstance(x,dict))
        if t.strip(): print('U:',t[:200].replace('\n',' | '))
" "$f" | tail -5; done

